    return this.secretaries.filter(secretary => secretary.status === 'Inactive').length;
  }
  // =========================================================
  // Get Secretary Initials
  // =========================================================
  getInitials(name) {
    return name.split(' ').filter(word => word.length > 0).map(word => word.charAt(0)).join('').substring(0, 2).toUpperCase();
  }
  // =========================================================
  // Filters
  // =========================================================
  applyFilters() {
    const search = this.searchValue.toLowerCase().trim();
    this.filteredSecretaries = this.secretaries.filter(secretary => {
      const matchesSearch = !search || secretary.name.toLowerCase().includes(search) || secretary.email.toLowerCase().includes(search) || secretary.department.toLowerCase().includes(search);
      const matchesDepartment = !this.selectedDepartment || secretary.department === this.selectedDepartment;
