import { Component, OnInit } from '@angular/core';

interface Secretary {
  userId: string;
  name: string;
  email: string;
  department: string;
  permission: string[];
  status: 'Active' | 'Inactive';
  createdAt: Date;
}

@Component({
  selector: 'app-secretaries',
  templateUrl: './secretaries.component.html',
  styleUrls: ['./secretaries.component.css']
})
export class SecretariesComponent implements OnInit {

  // =========================================================
  // Secretaries Data
  // =========================================================

  secretaries: Secretary[] = [

    {
      userId: 'USR001',
      name: 'Sara Ahmed',
      email: 'sara@gmail.com',
      department: 'Administration',
      permission: [
        'Students',
        'Groups'
      ],
      status: 'Active',
      createdAt: new Date()
    },

    {
      userId: 'USR002',
      name: 'Mariam Hassan',
      email: 'mariam@gmail.com',
      department: 'Finance',
      permission: [
        'Payments',
        'Students'
      ],
      status: 'Active',
      createdAt: new Date()
    },

    {
      userId: 'USR003',
      name: 'Nour Mohamed',
      email: 'nour@gmail.com',
      department: 'Registration',
      permission: [
        'Students',
        'Groups',
        'Attendance'
      ],
      status: 'Inactive',
      createdAt: new Date()
    }

  ];


  // Secretaries displayed after filtering

  filteredSecretaries: Secretary[] = [];


  // =========================================================
  // Departments
  // =========================================================

  departments: string[] = [
    'Administration',
    'Finance',
    'Registration',
    'Student Affairs',
    'Academic Affairs'
  ];


  // =========================================================
  // Available Permissions
  // =========================================================

  availablePermissions: string[] = [
    'Students',
    'Groups',
    'Teachers',
    'Attendance',
    'Payments',
    'Reports'
  ];


  // =========================================================
  // Filters
  // =========================================================

  searchValue: string = '';

  selectedDepartment: string = '';

  selectedStatus: string = '';


  // =========================================================
  // Modals
  // =========================================================

  isModalOpen: boolean = false;

  isDetailsModalOpen: boolean = false;


  selectedSecretary: Secretary | null = null;


  // =========================================================
  // New / Edited Secretary
  // =========================================================

  newSecretary = {

    userId: '',

    name: '',

    email: '',

    department: '',

    permission: [] as string[],

    status: 'Active' as 'Active' | 'Inactive'

  };


  // Used to determine whether we are adding or editing

  isEditMode: boolean = false;


  // =========================================================
  // Lifecycle
  // =========================================================

  ngOnInit(): void {

    this.filteredSecretaries = [
      ...this.secretaries
    ];

  }


  // =========================================================
  // Statistics
  // =========================================================

  get activeSecretariesCount(): number {

    return this.secretaries.filter(
      secretary => secretary.status === 'Active'
    ).length;

  }


  get inactiveSecretariesCount(): number {

    return this.secretaries.filter(
      secretary => secretary.status === 'Inactive'
    ).length;

  }


  // =========================================================
  // Get Secretary Initials
  // =========================================================

  getInitials(name: string): string {

    return name
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();

  }


  // =========================================================
  // Filters
  // =========================================================

  applyFilters(): void {

    const search = this.searchValue
      .toLowerCase()
      .trim();


    this.filteredSecretaries =
      this.secretaries.filter(secretary => {

        const matchesSearch =
          !search ||
          secretary.name
            .toLowerCase()
            .includes(search) ||

          secretary.email
            .toLowerCase()
            .includes(search) ||

          secretary.department
            .toLowerCase()
            .includes(search);


        const matchesDepartment =
          !this.selectedDepartment ||
          secretary.department === this.selectedDepartment;


        const matchesStatus =
          !this.selectedStatus ||
          secretary.status === this.selectedStatus;


        return (
          matchesSearch &&
          matchesDepartment &&
          matchesStatus
        );

      });

  }


  // =========================================================
  // Add Secretary
  // =========================================================

  onAddSecretaryClick(): void {

    this.isEditMode = false;

    this.selectedSecretary = null;


    this.newSecretary = {

      userId: '',

      name: '',

      email: '',

      department: '',

      permission: [],

      status: 'Active'

    };


    this.isModalOpen = true;

  }


  // =========================================================
  // Close Add / Edit Modal
  // =========================================================

  closeModal(): void {

    this.isModalOpen = false;

    this.selectedSecretary = null;

    this.isEditMode = false;

  }


  // =========================================================
  // Toggle Permission
  // =========================================================

  togglePermission(permission: string): void {

    const index =
      this.newSecretary.permission.indexOf(permission);


    if (index === -1) {

      this.newSecretary.permission.push(permission);

    } else {

      this.newSecretary.permission.splice(index, 1);

    }

  }


  // =========================================================
  // Save Secretary
  // =========================================================

  saveSecretary(): void {

    // Basic validation

    if (
      !this.newSecretary.name.trim() ||
      !this.newSecretary.email.trim() ||
      !this.newSecretary.department
    ) {

      return;

    }


    // =======================================================
    // Edit Existing Secretary
    // =======================================================

    if (
      this.isEditMode &&
      this.selectedSecretary
    ) {

      this.selectedSecretary.name =
        this.newSecretary.name.trim();


      this.selectedSecretary.email =
        this.newSecretary.email.trim();


      this.selectedSecretary.department =
        this.newSecretary.department;


      this.selectedSecretary.permission =
        [...this.newSecretary.permission];


      this.selectedSecretary.status =
        this.newSecretary.status;

    }


    // =======================================================
    // Add New Secretary
    // =======================================================

    else {

      const secretary: Secretary = {

        userId:
          'USR' +
          String(this.secretaries.length + 1)
            .padStart(3, '0'),

        name:
          this.newSecretary.name.trim(),

        email:
          this.newSecretary.email.trim(),

        department:
          this.newSecretary.department,

        permission:
          [...this.newSecretary.permission],

        status:
          this.newSecretary.status,

        createdAt:
          new Date()

      };


      this.secretaries.push(secretary);

    }


    // Refresh table

    this.applyFilters();


    // Close modal

    this.closeModal();

  }


  // =========================================================
  // View Secretary
  // =========================================================

  viewSecretary(secretary: Secretary): void {

    this.selectedSecretary = secretary;

    this.isDetailsModalOpen = true;

  }


  // =========================================================
  // Close Details Modal
  // =========================================================

  closeDetailsModal(): void {

    this.isDetailsModalOpen = false;

    this.selectedSecretary = null;

  }


  // =========================================================
  // Edit Secretary
  // =========================================================

  editSecretary(secretary: Secretary): void {

    this.selectedSecretary = secretary;

    this.isEditMode = true;


    this.newSecretary = {

      userId:
        secretary.userId,

      name:
        secretary.name,

      email:
        secretary.email,

      department:
        secretary.department,

      permission:
        [...secretary.permission],

      status:
        secretary.status

    };


    this.isModalOpen = true;

  }


  // =========================================================
  // Delete Secretary
  // =========================================================

  deleteSecretary(secretary: Secretary): void {

    const confirmed =
      confirm(
        `Are you sure you want to delete ${secretary.name}?`
      );


    if (!confirmed) {
      return;
    }


    const index =
      this.secretaries.indexOf(secretary);


    if (index !== -1) {

      this.secretaries.splice(index, 1);

      this.applyFilters();

    }

  }

}
<section class="secretaries-page">

  <!-- ==================== Header ==================== -->

  <div class="secretaries-header-banner">

    <div class="secretaries-page__header">

      <div>
        <h2 class="secretaries-page__title">Secretaries</h2>

        <p class="secretaries-page__subtitle">
          Manage and monitor all secretaries in your learning center.
        </p>
      </div>

      <div class="secretaries-page__actions">

        <button
          type="button"
          class="btn btn--primary"
          (click)="onAddSecretaryClick()"
        >

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >
            <path
              d="M12 5v14M5 12h14"
              stroke-linecap="round"
            ></path>
          </svg>

          Add Secretary

        </button>

      </div>

    </div>

  </div>


  <!-- ==================== Statistics ==================== -->

  <div class="stats-grid">

    <!-- Total Secretaries -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--blue">
        <i class="fa-solid fa-user-tie"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">Total Secretaries</span>

        <strong>{{ secretaries.length }}</strong>

        <span class="stat-description">
          All secretaries
        </span>

      </div>

    </div>


    <!-- Active Secretaries -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--green">
        <i class="fa-solid fa-user-check"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">Active Secretaries</span>

        <strong>{{ activeSecretariesCount }}</strong>

        <span class="stat-description">
          Currently active
        </span>

      </div>

    </div>


    <!-- Inactive Secretaries -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--orange">
        <i class="fa-solid fa-user-clock"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">Inactive Secretaries</span>

        <strong>{{ inactiveSecretariesCount }}</strong>

        <span class="stat-description">
          Currently inactive
        </span>

      </div>

    </div>


    <!-- Departments -->
    <div class="stat-card">

      <div class="stat-icon stat-icon--purple">
        <i class="fa-solid fa-building"></i>
      </div>

      <div class="stat-content">

        <span class="stat-title">Departments</span>

        <strong>{{ departments.length }}</strong>

        <span class="stat-description">
          Available departments
        </span>

      </div>

    </div>

  </div>


  <!-- ==================== Secretaries List ==================== -->

  <div class="secretaries-card">

    <!-- Card Header -->

    <div class="secretaries-card__header">

      <div>

        <h3>Secretaries List</h3>

        <p>
          {{ filteredSecretaries.length }} secretaries found
        </p>

      </div>


      <!-- Filters -->

      <div class="secretaries-filters">

        <!-- Department Filter -->

        <select
          [(ngModel)]="selectedDepartment"
          (change)="applyFilters()"
        >

          <option value="">
            All Departments
          </option>

          <option
            *ngFor="let department of departments"
            [value]="department"
          >
            {{ department }}
          </option>

        </select>


        <!-- Status Filter -->

        <select
          [(ngModel)]="selectedStatus"
          (change)="applyFilters()"
        >

          <option value="">
            All Status
          </option>

          <option value="Active">
            Active
          </option>

          <option value="Inactive">
            Inactive
          </option>

        </select>


        <!-- Search -->

        <div class="search-box">

          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
          >

            <circle
              cx="11"
              cy="11"
              r="8"
            ></circle>

            <path
              d="m21 21-4.3-4.3"
            ></path>

          </svg>

          <input
            type="text"
            placeholder="Search secretaries..."
            [(ngModel)]="searchValue"
            (input)="applyFilters()"
          />

        </div>

      </div>

    </div>


    <!-- ==================== Secretaries Table ==================== -->

    <div class="table-wrapper">

      <table class="secretaries-table">

        <thead>

          <tr>

            <th>SECRETARY</th>

            <th>EMAIL</th>

            <th>DEPARTMENT</th>

            <th>PERMISSIONS</th>

            <th>STATUS</th>

            <th>ACTIONS</th>

          </tr>

        </thead>


        <tbody>

          <!-- Secretary Rows -->

          <tr
            *ngFor="let secretary of filteredSecretaries"
          >

            <!-- Secretary -->

            <td>

              <div class="secretary-cell">

                <div class="secretary-avatar">
                  {{ getInitials(secretary.name) }}
                </div>

                <div class="secretary-info">

                  <strong>
                    {{ secretary.name }}
                  </strong>

                  <span>
                    Secretary
                  </span>

                </div>

              </div>

            </td>


            <!-- Email -->

            <td>

              <span class="text-muted">
                {{ secretary.email }}
              </span>

            </td>


            <!-- Department -->

            <td>

              <span class="department-badge">
                {{ secretary.department }}
              </span>

            </td>


            <!-- Permissions -->

            <td>

              <div class="permissions-list">

                <span
                  class="permission-badge"
                  *ngFor="let permission of secretary.permission"
                >
                  {{ permission }}
                </span>

              </div>

            </td>


            <!-- Status -->

            <td>

              <span
                class="status-badge"
                [class.status-badge--active]="secretary.status === 'Active'"
                [class.status-badge--inactive]="secretary.status === 'Inactive'"
              >

                <span></span>

                {{ secretary.status }}

              </span>

            </td>


            <!-- Actions -->

            <td>

              <div class="actions">

                <!-- View -->

                <button
                  type="button"
                  title="View"
                  (click)="viewSecretary(secretary)"
                >
                  <i class="fa-regular fa-eye"></i>
                </button>


                <!-- Edit -->

                <button
                  type="button"
                  title="Edit"
                  (click)="editSecretary(secretary)"
                >
                  <i class="fa-solid fa-pen"></i>
                </button>


                <!-- Delete -->

                <button
                  type="button"
                  title="Delete"
                  (click)="deleteSecretary(secretary)"
                >
                  <i class="fa-regular fa-trash-can"></i>
                </button>

              </div>

            </td>

          </tr>


          <!-- ==================== Empty State ==================== -->

          <tr
            *ngIf="filteredSecretaries.length === 0"
          >

            <td
              colspan="6"
              class="empty-state"
            >

              <div class="empty-state__icon">

                <i class="fa-solid fa-user-tie"></i>

              </div>

              <strong>
                No secretaries found
              </strong>

              <span>
                Try changing your search or filters.
              </span>

            </td>

          </tr>

        </tbody>

      </table>

    </div>

  </div>

</section>


<!-- ========================================================= -->
<!-- Add / Edit Secretary Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isModalOpen"
>

  <div class="modal-card">

    <h3>
      {{ isEditMode ? 'Edit Secretary' : 'New Secretary' }}
    </h3>


    <!-- Secretary Name -->

    <div class="form-group">

      <label>
        Secretary Name
      </label>

      <input
        type="text"
        [(ngModel)]="newSecretary.name"
        placeholder="Enter secretary name"
      />

    </div>


    <!-- Email -->

    <div class="form-group">

      <label>
        Email
      </label>

      <input
        type="email"
        [(ngModel)]="newSecretary.email"
        placeholder="Enter email"
      />

    </div>


    <!-- Department -->

    <div class="form-group">

      <label>
        Department
      </label>

      <select
        [(ngModel)]="newSecretary.department"
      >

        <option value="">
          Select department
        </option>

        <option
          *ngFor="let department of departments"
          [value]="department"
        >
          {{ department }}
        </option>

      </select>

    </div>


    <!-- Permissions -->

    <div class="form-group">

      <label>
        Permissions
      </label>

      <div class="permission-options">

        <label
          class="checkbox-option"
          *ngFor="let permission of availablePermissions"
        >

          <input
            type="checkbox"
            [checked]="newSecretary.permission.includes(permission)"
            (change)="togglePermission(permission)"
          />

          <span>
            {{ permission }}
          </span>

        </label>

      </div>

    </div>


    <!-- Status -->

    <div class="form-group">

      <label>
        Status
      </label>

      <select
        [(ngModel)]="newSecretary.status"
      >

        <option value="Active">
          Active
        </option>

        <option value="Inactive">
          Inactive
        </option>

      </select>

    </div>


    <!-- Modal Actions -->

    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--ghost-dark"
        (click)="closeModal()"
      >
        Cancel
      </button>


      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="saveSecretary()"
      >

        {{ isEditMode ? 'Update Secretary' : 'Save Secretary' }}

      </button>

    </div>

  </div>

</div>


<!-- ========================================================= -->
<!-- Secretary Details Modal -->
<!-- ========================================================= -->

<div
  class="modal-overlay"
  *ngIf="isDetailsModalOpen && selectedSecretary"
>

  <div class="modal-card">

    <h3>
      Secretary Details
    </h3>


    <div class="secretary-details">

      <div>

        <strong>
          Secretary Name:
        </strong>

        {{ selectedSecretary.name }}

      </div>


      <div>

        <strong>
          Email:
        </strong>

        {{ selectedSecretary.email }}

      </div>


      <div>

        <strong>
          Department:
        </strong>

        {{ selectedSecretary.department }}

      </div>


      <div>

        <strong>
          Permissions:
        </strong>

        <div class="details-permissions">

          <span
            class="permission-badge"
            *ngFor="let permission of selectedSecretary.permission"
          >
            {{ permission }}
          </span>

        </div>

      </div>


      <div>

        <strong>
          Status:
        </strong>

        {{ selectedSecretary.status }}

      </div>


    </div>


    <!-- Modal Actions -->

    <div class="modal-actions">

      <button
        type="button"
        class="btn btn--primary modal-save-btn"
        (click)="closeDetailsModal()"
      >
        Close
      </button>

    </div>

  </div>

</div>
